KG42.register("rules-b66ac8c00c4d0c6a80d38bdf",{"id":"42-data_center_space_time_flexibility::v141-c-R007","paper":"42-data_center_space_time_flexibility","record":{"rule_id":"v141-c-R007","mechanism_id":"v141-a-M02","name":"Social-welfare clearing objective","process_stage":"clearing","market_meaning":"The submitted requested load limits the total load allocated across the flexible consumer's offered nodes in welfare clearing. Scope: The single flexible consumer's total allocation across its offered delivery nodes. The welfare formulation minimizes supply and transmission costs minus the flexible consumer's bid-valued total served load. Scope: Load-disaggregation clearing for the single flexible consumer and its offered delivery nodes. The formulation enforces nodal power balance, nonnegative disaggregated loads and DC network feasibility. Scope: Feasibility of load-disaggregation welfare clearing.","independence_rationale":"Relations governed by the approved function clearing.social_welfare under the fixed relation-ownership template. Conditional branches retain their explicit scope in local constraints.","V":["bidding.demand","clearing.social_welfare"],"E":[{"edge_id":"v141-c-R007-E001","source":"bidding.demand","target":"clearing.social_welfare","type":"limits","constraint_ids":["v141-c-R007-C001"],"evidence_ids":["v141-b-g01-e038","v141-b-g01-e040"]}],"omega":{"market_type":"DEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"clearing","context_text":"Feasibility of load-disaggregation welfare clearing. | Load-disaggregation clearing for the single flexible consumer and its offered delivery nodes. | The single flexible consumer's total allocation across its offered delivery nodes.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-e038","v141-b-g01-e040","v141-b-g02-e009","v141-b-g02-e016"]},"x":[{"variable_id":"v141-c-R007-x-dn","symbol":"d_n","meaning":"Cleared load allocated to the single flexible consumer at offered delivery node n","kind":"operational","domain":"n ∈ N_d; d_n ≥ 0","unit":null,"indices":["n"],"evidence_ids":["v141-b-g01-e038","v141-b-g02-e009"]},{"variable_id":"v141-c-R007-x-pi","symbol":"p_i","meaning":"Cleared power injection of supplier i in the welfare clearing formulation","kind":"operational","domain":"i ∈ S; p ∈ C_p (supplier capacity set)","unit":null,"indices":["i"],"evidence_ids":["v141-b-g02-e009"]},{"variable_id":"v141-c-R007-x-fk","symbol":"f_k","meaning":"Cleared flow on directed transmission edge k","kind":"operational","domain":"k ∈ K; f must satisfy the DC flow equation (2.16f) with θ ∈ C_θ","unit":null,"indices":["k"],"evidence_ids":["v141-b-g02-e009"]},{"variable_id":"v141-c-R007-x-theta","symbol":"θ_n","meaning":"Phase angle at node n","kind":"operational","domain":"n ∈ N; θ ∈ C_θ (phase-angle feasibility set)","unit":null,"indices":["n"],"evidence_ids":["v141-b-g02-e009"]}],"theta":[{"parameter_id":"v141-c-R007-theta-alphap","symbol":"α^p_i","meaning":"Bid price coefficient of supplier i in the clearing objective","value":{"kind":"symbolic","number_value":null,"text_value":"supplier bid price"},"unit":null,"indices":["i"],"evidence_ids":["v141-b-g02-e009"]},{"parameter_id":"v141-c-R007-theta-alphaf","symbol":"α^f_k","meaning":"Bid price/cost coefficient of directed transmission edge k in the clearing objective","value":{"kind":"symbolic","number_value":null,"text_value":"transmission-edge bid price"},"unit":null,"indices":["k"],"evidence_ids":["v141-b-g02-e009"]},{"parameter_id":"v141-c-R007-theta-alphad","symbol":"α^d","meaning":"Bid price submitted by the single flexible consumer for requested load","value":{"kind":"symbolic","number_value":null,"text_value":"flexible-consumer bid price"},"unit":null,"indices":[],"evidence_ids":["v141-b-g01-e038","v141-b-g02-e009"]},{"parameter_id":"v141-c-R007-theta-bard","symbol":"\\bar d","meaning":"Requested load cap submitted by the flexible consumer; total served load cannot exceed it","value":{"kind":"symbolic","number_value":null,"text_value":"requested load cap"},"unit":null,"indices":[],"evidence_ids":["v141-b-g01-e038","v141-b-g02-e009"]},{"parameter_id":"v141-c-R007-theta-Nd","symbol":"\\mathcal{N}_d","meaning":"Set of delivery nodes offered by the single flexible consumer, with N_d ⊆ N","value":{"kind":"symbolic","number_value":null,"text_value":"\\mathcal{N}_d \\subseteq \\mathcal{N}"},"unit":null,"indices":[],"evidence_ids":["v141-b-g01-e011","v141-b-g01-e038"]},{"parameter_id":"v141-c-R007-theta-Bl","symbol":"B_l","meaning":"Line susceptance for transmission line l","value":{"kind":"symbolic","number_value":null,"text_value":"line susceptance"},"unit":null,"indices":["l"],"evidence_ids":["v141-b-g02-e009"]},{"parameter_id":"v141-c-R007-theta-Cp","symbol":"C_p","meaning":"Feasible capacity set for supplier injections p, as used in p ∈ C_p","value":{"kind":"symbolic","number_value":null,"text_value":"supplier capacity set"},"unit":null,"indices":[],"evidence_ids":["v141-b-g02-e009"]},{"parameter_id":"v141-c-R007-theta-Ctheta","symbol":"C_θ","meaning":"Feasible phase-angle set, as used in θ ∈ C_θ","value":{"kind":"symbolic","number_value":null,"text_value":"phase-angle capacity set"},"unit":null,"indices":[],"evidence_ids":["v141-b-g02-e009"]}],"phi":[{"constraint_id":"v141-c-R007-C001","kind":"mathematical","role":"core","statement":"The submitted requested load limits the total load allocated across the flexible consumer's offered nodes in welfare clearing. Scope: The single flexible consumer's total allocation across its offered delivery nodes.","expression":"0 \\le \\sum_{n\\in\\mathcal{N}_{d}} d_{n} \\le \\bar{d}","formalization_origin":"source","template_id":null,"members":["bidding.demand","clearing.social_welfare"],"variable_refs":["v141-c-R007-x-dn"],"parameter_refs":["v141-c-R007-theta-bard","v141-c-R007-theta-Nd"],"evidence_ids":["v141-b-g01-e038","v141-b-g01-e040","v141-b-g02-e009"]},{"constraint_id":"v141-c-R007-C002","kind":"mathematical","role":"core","statement":"The welfare formulation minimizes supply and transmission costs minus the flexible consumer's bid-valued total served load. Scope: Load-disaggregation clearing for the single flexible consumer and its offered delivery nodes.","expression":"\\min_{d,p,f,\\theta} \\sum_{i\\in\\mathcal{S}} \\alpha^{p}_{i} p_{i} + \\sum_{k\\in\\mathcal{K}} \\alpha^{f}_{k} f_{k} - \\alpha^{d} \\sum_{n\\in\\mathcal{N}_{d}} d_{n}","formalization_origin":"source","template_id":null,"members":["clearing.social_welfare"],"variable_refs":["v141-c-R007-x-dn","v141-c-R007-x-pi","v141-c-R007-x-fk","v141-c-R007-x-theta"],"parameter_refs":["v141-c-R007-theta-alphap","v141-c-R007-theta-alphaf","v141-c-R007-theta-alphad","v141-c-R007-theta-Nd"],"evidence_ids":["v141-b-g02-e009","v141-b-g01-e039"]},{"constraint_id":"v141-c-R007-C003","kind":"mathematical","role":"core","statement":"The formulation enforces nodal power balance, nonnegative disaggregated loads and DC network feasibility. Scope: Feasibility of load-disaggregation welfare clearing.","expression":"\\sum_{k\\in\\mathcal{K}^{rec}_{n}} f_{k} + \\sum_{i\\in\\mathcal{S}_{n}} p_{i} = \\sum_{k\\in\\mathcal{K}^{snd}_{n}} f_{k} + d_{n},\\quad n\\in\\mathcal{N}_{d};\\quad \\sum_{k\\in\\mathcal{K}^{rec}_{n}} f_{k} + \\sum_{i\\in\\mathcal{S}_{n}} p_{i} = \\sum_{k\\in\\mathcal{K}^{snd}_{n}} f_{k},\\quad n\\in\\mathcal{N}\\setminus\\mathcal{N}_{d};\\quad d_{n}\\ge 0,\\quad n\\in\\mathcal{N}_{d};\\quad f_{l^{+}}-f_{l^{-}}=B_{l}(\\theta_{snd(l)}-\\theta_{rec(l)}),\\quad l\\in\\mathcal{L};\\quad p\\in C_{p},\\ \\theta\\in C_{\\theta}","formalization_origin":"source","template_id":null,"members":["clearing.social_welfare"],"variable_refs":["v141-c-R007-x-dn","v141-c-R007-x-pi","v141-c-R007-x-fk","v141-c-R007-x-theta"],"parameter_refs":["v141-c-R007-theta-Nd","v141-c-R007-theta-Bl","v141-c-R007-theta-Cp","v141-c-R007-theta-Ctheta"],"evidence_ids":["v141-b-g02-e009","v141-b-g02-e016","v141-b-g01-e039"]}],"pi":[{"evidence_id":"v141-b-g01-e038","location":{"location_id":"src-1c03246cb9-p05-c2r3__v141-a-M02-bidding","page":5,"printed_page":null,"section":"2.3 Basic formulation with flexible consumers","anchor_text":"2) Understanding the effect of transmission capacity on prices will become relevant for the formulat","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"formula"},"source_text":"We now expand the previous clearing formulation by incorporating flexible consumers; specifically, we consider flexible consumers that offer load-shifting flexibility by exploiting the availability of multiple DaCes placed at different nodes. For simplicity in the presentation, we consider a single flexible consumer. Suppose that this consumer submits a bid for requested load \\bar{d} with bid price \\alpha^{d}; the requested load can be served/delivered at a set of nodes \\mathcal{N}_{d}\\subseteq\\mathcal{N}. Each node n\\in\\mathcal{N}_{d} receives a partial load d_{n}\\ge 0; the total load served to the consumer is \\sum_{n\\in\\mathcal{N}_{d}}d_{n} and satisfies \\sum_{n\\in\\mathcal{N}_{d}}d_{n}\\le\\bar{d} (total load served cannot exceed the requested load)."},{"evidence_id":"v141-b-g01-e040","location":{"location_id":"src-1c03246cb9-p05-c2r4__v141-a-M02-clearing","page":5,"printed_page":null,"section":"2.3 Basic formulation with flexible consumers","anchor_text":"𝑑,𝑝,𝑓,𝜃 𝑘 𝑖∈ 𝑘∈ 𝑛∈𝑑he ∑ ∑ ∑ ch s.t. 𝑓𝑘+ 𝑝𝑖= 𝑓𝑘+ 𝑑𝑛 (𝜋𝑛), 𝑛∈𝑑 (2.16b) le 𝑘∈rec𝑛 𝑖∈𝑛 𝑘∈snd𝑛 it ","equation_id":"2.16","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"formula"},"source_text":"From the structure of the surplus function we see that the formulation aims to maximize the total load delivered to the flexible consumer."},{"evidence_id":"v141-b-g02-e009","location":{"location_id":"src-1c03246cb9-p05-c2r4__v141-a-M02-clearing","page":5,"printed_page":null,"section":"2.3 Basic formulation with flexible consumers","anchor_text":"𝑑,𝑝,𝑓,𝜃 𝑘 𝑖∈ 𝑘∈ 𝑛∈𝑑he ∑ ∑ ∑ ch s.t. 𝑓𝑘+ 𝑝𝑖= 𝑓𝑘+ 𝑑𝑛 (𝜋𝑛), 𝑛∈𝑑 (2.16b) le 𝑘∈rec𝑛 𝑖∈𝑛 𝑘∈snd𝑛 it ","equation_id":"2.16","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"formula"},"source_text":"The clearing problem is: min_{d,p,f,\\theta} \\sum_{i\\in S}\\alpha^{p}_{i}p_i+\\sum_{k\\in K}\\alpha^{f}_{k}f_k-\\alpha^d\\sum_{n\\in N_d}d_n (2.16a) s.t. \\sum_{k\\in K^{rec}_n}f_k+\\sum_{i\\in S_n}p_i=\\sum_{k\\in K^{snd}_n}f_k+d_n (\\pi_n), n\\in N_d (2.16b); \\sum_{k\\in K^{rec}_n}f_k+\\sum_{i\\in S_n}p_i=\\sum_{k\\in K^{snd}_n}f_k (\\pi_n), n\\in N\\setminus N_d (2.16c); 0\\le\\sum_{n\\in N_d}d_n\\le\\bar d (2.16d); d_n\\ge0, n\\in N_d (2.16e); f_{l^+}-f_{l^-}=B_l(\\theta_{snd(l)}-\\theta_{rec(l)}), l\\in L (2.16f); p\\in C_p, \\theta\\in C_\\theta (2.16g)."},{"evidence_id":"v141-b-g02-e016","location":{"location_id":"src-1c03246cb9-p06-c2r1__v141-a-M02-settlement","page":6,"printed_page":null,"section":"2.3 Basic formulation with flexible consumers","anchor_text":"Applied Energy 326 (2022) 119930 𝑑) Market clearance is guaranteed by satisfaction of the power bala","equation_id":"2.22","figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"formula"},"source_text":"Market clearance is guaranteed by satisfaction of the power balance constraints (2.16b), (2.16c). Furthermore, (2.19)-(2.21) show that the formulation (2.16) delivers an optimal price and allocation that maximize profit for the flexible consumer, each of the suppliers, and the transmission network. From the balance constraints (2.16b), (2.16c) we have: 0=\\sum_{n\\in N}\\pi_n\\left(\\sum_{k\\in K^{rec}_n}f_k+\\sum_{i\\in S_n}p_i-\\sum_{k\\in K^{snd}_n}f_k-\\sum_{j\\in D_n}d_j\\right) (2.22). Basic manipulations reveal that this expression implies revenue adequacy."},{"evidence_id":"v141-b-g01-e011","location":{"location_id":"src-1c03246cb9-p03-c1r4__v141-a-M02-participation","page":3,"printed_page":null,"section":"2.1 Basic notation and terminology","anchor_text":"our formulation does not enforce a hard minimum load (load shedding be is allowed to all levels). Ho","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"definition"},"source_text":"A standard (inflexible) consumer requests that the cleared load d_j is delivered at a single node n(j) \\in \\mathcal{N}. A flexible consumer (a DaCe owner), on the other hand, offers the possibility that the cleared load d_j is delivered at a set of possible nodes \\mathcal{N}_{d} \\subseteq N; in other words, the cleared load d_j can be disaggregated and individual portions are delivered at different nodes. We will see that this load disaggregation scheme can be seen as a spatial, load-shifting mechanism that can be modeled using virtual links. For simplicity, we will not make a distinction between DaCe owners and inflexible consumers. This is because an inflexible consumer can be modeled as a flexible consumer with \\mathcal{N}_{d}=\\{n(j)\\} (it offers one node option for the load to be delivered)."},{"evidence_id":"v141-b-g01-e039","location":{"location_id":"src-1c03246cb9-p05-c2r3__v141-a-M02-clearing","page":5,"printed_page":null,"section":"2.3 Basic formulation with flexible consumers","anchor_text":"2) Understanding the effect of transmission capacity on prices will become relevant for the formulat","equation_id":"2.16","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"formula"},"source_text":"The clearing problem is: \\min_{d,p,f,\\theta} \\sum_{i\\in\\mathcal{S}}\\alpha^{p}_{i}p_{i}+\\sum_{k\\in\\mathcal{K}}\\alpha^{f}_{k}f_{k}-\\alpha^{d}\\sum_{n\\in\\mathcal{N}_{d}}d_{n} \\quad (2.16a) s.t. \\sum_{k\\in\\mathcal{K}^{rec}_{n}}f_{k}+\\sum_{i\\in\\mathcal{S}_{n}}p_{i}=\\sum_{k\\in\\mathcal{K}^{snd}_{n}}f_{k}+d_{n},\\quad (\\pi_n),\\ n\\in\\mathcal{N}_{d} \\quad (2.16b) \\sum_{k\\in\\mathcal{K}^{rec}_{n}}f_{k}+\\sum_{i\\in\\mathcal{S}_{n}}p_{i}=\\sum_{k\\in\\mathcal{K}^{snd}_{n}}f_{k},\\quad (\\pi_n),\\ n\\in\\mathcal{N}\\setminus\\mathcal{N}_{d} \\quad (2.16c) 0\\le\\sum_{n\\in\\mathcal{N}_{d}}d_{n}\\le\\bar{d} \\quad (2.16d) d_{n}\\ge 0,\\quad n\\in\\mathcal{N}_{d} \\quad (2.16e) f_{l^{+}}-f_{l^{-}}=B_{l}(\\theta_{snd(l)}-\\theta_{rec(l)}),\\quad l\\in\\mathcal{L} \\quad (2.16f) p\\in C_{p},\\ \\theta\\in C_{\\theta} \\quad (2.16g)."}],"field_notes":{"empty_E_reason":null,"empty_x_reason":null,"empty_theta_reason":null},"evidence_basis":"explicit","implementation_status":"unimplemented","status":"needs_review","lead_ids":["v141-a-M02-bidding","v141-a-M02-clearing","v141-a-M02-participation","v141-a-M02-settlement"],"extras":{"decision_anchor":"clearing.social_welfare","graph_fact_supports":[[{"evidence_id":"v141-b-g01-e038","quote":"this consumer submits a bid for requested load"},{"evidence_id":"v141-b-g01-e038","quote":"total load served cannot exceed the requested load"},{"evidence_id":"v141-b-g01-e040","quote":"From the structure of the surplus function we see that the formulation aims to maximize the total load delivered to the flexible consumer."}],[{"evidence_id":"v141-b-g02-e009","quote":"The clearing problem is: min_{d,p,f,\\theta} \\sum_{i\\in S}\\alpha^{p}_{i}p_i+\\sum_{k\\in K}\\alpha^{f}_{k}f_k-\\alpha^d\\sum_{n\\in N_d}d_n (2.16a)"}],[{"evidence_id":"v141-b-g02-e016","quote":"Market clearance is guaranteed by satisfaction of the power balance constraints (2.16b), (2.16c)."},{"evidence_id":"v141-b-g02-e009","quote":"d_n\\ge0, n\\in N_d (2.16e); f_{l^+}-f_{l^-}=B_l(\\theta_{snd(l)}-\\theta_{rec(l)}), l\\in L (2.16f)"}]],"C2_formalization":{"graph_sha256":"27e96eab3ed0d0c38dc192b2b7fd547cabeac287e89a897054420d05e72dc934","applicability":"formalized","reason":"The source clearing formulation (2.16) explicitly supplies the welfare objective, the requested-load cap on aggregate flexible load, and the nodal-balance, nonnegativity, DC-flow, and capacity-set constraints. The formalization uses only the frozen nodes bidding.demand and clearing.social_welfare and the existing limits edge. B evidence remains unreviewed under the experiment.","bindings":[{"object_id":"v141-c-R007-x-dn","node_ids":["bidding.demand","clearing.social_welfare"],"edge_ids":["v141-c-R007-E001"],"rationale":"The cleared disaggregated load d_n is the flexible consumer's allocation across offered nodes in the welfare clearing and is constrained by the submitted requested load through the bidding.demand-to-clearing.social_welfare limits edge."},{"object_id":"v141-c-R007-x-pi","node_ids":["clearing.social_welfare"],"edge_ids":[],"rationale":"Supplier injection p_i is an optimization variable inside the social-welfare clearing formulation. The frozen rule graph has no separate supplier-bid or supply node, so it is bound to the clearing node only."},{"object_id":"v141-c-R007-x-fk","node_ids":["clearing.social_welfare"],"edge_ids":[],"rationale":"Directed-edge transmission flow f_k appears in the welfare objective and DC-flow feasibility of the clearing formulation. The frozen rule graph has no transmission node, so it is bound to clearing.social_welfare."},{"object_id":"v141-c-R007-x-theta","node_ids":["clearing.social_welfare"],"edge_ids":[],"rationale":"Phase angle θ_n appears in the DC-flow feasibility constraints of the welfare clearing formulation. The frozen rule graph has no transmission node, so it is bound to clearing.social_welfare."},{"object_id":"v141-c-R007-theta-alphap","node_ids":["clearing.social_welfare"],"edge_ids":[],"rationale":"Supplier bid coefficient α^p_i parameterizes the supply-cost term in the welfare objective. It is bound to the clearing node because no separate supplier node exists in this rule graph."},{"object_id":"v141-c-R007-theta-alphaf","node_ids":["clearing.social_welfare"],"edge_ids":[],"rationale":"Transmission-edge bid coefficient α^f_k parameterizes the transmission-cost term in the welfare objective. It is bound to the clearing node because no separate transmission node exists in this rule graph."},{"object_id":"v141-c-R007-theta-alphad","node_ids":["bidding.demand","clearing.social_welfare"],"edge_ids":["v141-c-R007-E001"],"rationale":"The flexible consumer's bid price α^d originates in the demand bid and values served load in the clearing objective, linking bidding.demand to clearing.social_welfare through the existing limits edge."},{"object_id":"v141-c-R007-theta-bard","node_ids":["bidding.demand","clearing.social_welfare"],"edge_ids":["v141-c-R007-E001"],"rationale":"The requested-load cap \\bar d originates in the flexible consumer's bid and limits total allocated load in clearing, matching the existing bidding.demand-to-clearing.social_welfare limits edge."},{"object_id":"v141-c-R007-theta-Nd","node_ids":["bidding.demand","clearing.social_welfare"],"edge_ids":["v141-c-R007-E001"],"rationale":"The offered delivery-node set N_d is defined by the flexible consumer's bid and determines the nodes over which cleared load is summed in the welfare formulation; this is exactly the bid-to-clearing scope represented by the limits edge."},{"object_id":"v141-c-R007-theta-Bl","node_ids":["clearing.social_welfare"],"edge_ids":[],"rationale":"Line susceptance B_l is a fixed transmission parameter in the DC-flow equation (2.16f), represented inside the clearing formulation."},{"object_id":"v141-c-R007-theta-Cp","node_ids":["clearing.social_welfare"],"edge_ids":[],"rationale":"C_p is the feasible supplier-capacity set used by p ∈ C_p in the clearing formulation; it is represented inside the clearing node."},{"object_id":"v141-c-R007-theta-Ctheta","node_ids":["clearing.social_welfare"],"edge_ids":[],"rationale":"C_θ is the feasible phase-angle set used by θ ∈ C_θ in the clearing formulation; it is represented inside the clearing node."},{"object_id":"v141-c-R007-C001","node_ids":["bidding.demand","clearing.social_welfare"],"edge_ids":["v141-c-R007-E001"],"rationale":"Constraint (2.16d) formalizes the requested-load cap on the flexible consumer's total disaggregated allocation, exactly the relation represented by the bidding.demand-to-clearing.social_welfare limits edge."},{"object_id":"v141-c-R007-C002","node_ids":["clearing.social_welfare"],"edge_ids":[],"rationale":"The objective (2.16a) is the social-welfare clearing objective, represented inside clearing.social_welfare."},{"object_id":"v141-c-R007-C003","node_ids":["clearing.social_welfare"],"edge_ids":[],"rationale":"Nodal balance, nonnegativity, DC-flow, and capacity-set constraints (2.16b), (2.16c), (2.16e), (2.16f), (2.16g) define feasibility of the clearing formulation and are represented inside clearing.social_welfare."}],"revision_requests":[]}},"quarantined_references":[]}});
